#include "engine/angle.h"

#include "trig_tables.h" /* generated by tools/gen_trig.c into build/gen */

#define SLOPEBITS 11 /* tantoangle has 2^11 + 1 entries */

_Static_assert(sizeof(finesine) / sizeof(finesine[0]) == FINEANGLES + FINEANGLES / 4,
               "finesine size");
_Static_assert(sizeof(tantoangle) / sizeof(tantoangle[0]) == (1 << SLOPEBITS) + 1,
               "tantoangle size");

fix_t fine_sin(angle_t a)
{
    return finesine[a >> ANGLETOFINESHIFT];
}

fix_t fine_cos(angle_t a)
{
    return finesine[(a >> ANGLETOFINESHIFT) + FINEANGLES / 4];
}

static uint32_t mag(fix_t v)
{
    /* Unsigned negation: |INT32_MIN| = 2^31 without overflow. */
    return v < 0 ? 0u - (uint32_t)v : (uint32_t)v;
}

/* atan(num/den) for 0 <= num <= den, den > 0, in angle units 0..ANG45. */
static angle_t atan_octant(uint32_t num, uint32_t den)
{
    uint64_t idx = (((uint64_t)num << SLOPEBITS) + den / 2) / den;
    return tantoangle[idx];
}

angle_t angle_of(fix_t dx, fix_t dy)
{
    uint32_t ax = mag(dx), ay = mag(dy);
    if (ax == 0 && ay == 0)
        return 0;

    /* Angle in the first quadrant, 0..ANG90. */
    angle_t a = ax >= ay ? atan_octant(ay, ax) : (angle_t)(ANG90 - atan_octant(ax, ay));

    if (dx >= 0)
        return dy >= 0 ? a : (angle_t)(0u - a);
    return dy >= 0 ? (angle_t)(ANG180 - a) : (angle_t)(ANG180 + a);
}

fix_t fix_dist(fix_t dx, fix_t dy)
{
    uint64_t ax = mag(dx), ay = mag(dy);
    /* Each square <= 2^62, the sum <= 2^63: fits in uint64. The root of a
     * 32.32 value is 16.16. */
    uint32_t d = isqrt64(ax * ax + ay * ay);
    return d > INT32_MAX ? INT32_MAX : (fix_t)d;
}
